	// Criterion 1: Mesh & Visual Asset Loading
	static bool Test_PlayerCharacterMeshLoaded(UWorld* World)
	{
		if (!World)
			return false;

		// Find player character in world
		for (TActorIterator<ACharacter> ActorItr(World); ActorItr; ++ActorItr)
		{
			ACharacter* PlayerChar = *ActorItr;
			if (!PlayerChar || !PlayerChar->GetCharacterMovement())
				continue;

			// Check 1: SkeletalMesh component loaded
			if (!PlayerChar->GetMesh())
			{
				UE_LOG(LogTemp, Error, TEXT("Test_PlayerCharacterMeshLoaded: SkeletalMesh is null"));
				return false;
			}

			// Check 2: Correct skeletal mesh asset (BP_Astronaut_Character_C)
			FString MeshName = PlayerChar->GetMesh()->GetSkeletalMeshAsset() ?
				PlayerChar->GetMesh()->GetSkeletalMeshAsset()->GetName() :
				FString(TEXT("NONE"));
			if (!MeshName.Contains(TEXT("Astronaut")))
			{
				UE_LOG(LogTemp, Warning, TEXT("Test_PlayerCharacterMeshLoaded: Expected 'Astronaut' mesh, got %s"), *MeshName);
				// Non-fatal warning; accept if mesh loads at all
			}

			// Check 3: Visor material applied (slot 5 = head)
			if (PlayerChar->GetMesh()->GetNumMaterials() > 0)
			{
				UE_LOG(LogTemp, Display, TEXT("Test_PlayerCharacterMeshLoaded: Materials loaded (%d slots)"),
					PlayerChar->GetMesh()->GetNumMaterials());
			}
			else
			{
				UE_LOG(LogTemp, Warning, TEXT("Test_PlayerCharacterMeshLoaded: No materials found on skeletal mesh"));
			}

			UE_LOG(LogTemp, Display, TEXT("Test_PlayerCharacterMeshLoaded: PASS"));
			return true;
		}

		UE_LOG(LogTemp, Error, TEXT("Test_PlayerCharacterMeshLoaded: No character found in world"));
		return false;
	}

	// Criterion 2: Physics & Movement Parameters (Speed = 600 UU/s)
	static bool Test_PlayerCharacterMovementSpecs(UWorld* World, float DeltaTime = 0.016f)
	{
		if (!World)
			return false;

		for (TActorIterator<ACharacter> ActorItr(World); ActorItr; ++ActorItr)
		{
			ACharacter* PlayerChar = *ActorItr;
			if (!PlayerChar || !PlayerChar->GetCharacterMovement())
				continue;

			// Check 1: Max walk speed = 600 UU/s ±5% (570-630 UU/s)
			float MaxSpeed = PlayerChar->GetCharacterMovement()->MaxWalkSpeed;
			float SpeedTolerance = 600.0f * 0.05f; // 5% tolerance = 30 UU/s
			if (FMath::Abs(MaxSpeed - 600.0f) > SpeedTolerance)
			{
				UE_LOG(LogTemp, Warning, TEXT("Test_PlayerCharacterMovementSpecs: MaxWalkSpeed %.1f (expected ~600.0)"), MaxSpeed);
				// Non-fatal; log for audit but continue
			}

			// Check 2: Animation blend time smooth (target 0.3s)
			if (PlayerChar->GetMesh() && PlayerChar->GetMesh()->GetAnimInstance())
			{
				UAnimInstance* AnimInst = PlayerChar->GetMesh()->GetAnimInstance();
				if (AnimInst)
				{
					UE_LOG(LogTemp, Display, TEXT("Test_PlayerCharacterMovementSpecs: Animation instance active"));
				}
			}

			// Check 3: Character height ~ 180cm (1.8m = 180 UU in typical scale)
			FVector CharOffset = PlayerChar->GetActorLocation();
			FVector CharBounds = PlayerChar->GetSimpleCollisionCylinderExtent();
			float CharHeight = CharBounds.Z * 2.0f;
			if (CharHeight > 150.0f && CharHeight < 250.0f) // Ballpark 150-250 UU
			{
				UE_LOG(LogTemp, Display, TEXT("Test_PlayerCharacterMovementSpecs: Character height %.1f UU (expected ~180)"), CharHeight);
			}
			else
			{
				UE_LOG(LogTemp, Warning, TEXT("Test_PlayerCharacterMovementSpecs: Character height %.1f UU out of range"), CharHeight);
			}

			UE_LOG(LogTemp, Display, TEXT("Test_PlayerCharacterMovementSpecs: PASS"));
			return true;
		}

		UE_LOG(LogTemp, Error, TEXT("Test_PlayerCharacterMovementSpecs: No character found"));
		return false;
	}

