	// Criterion 4: Save/Load Data Integrity
	static bool Test_PlayerCharacterStatePersistence(UWorld* World)
	{
		if (!World)
			return false;

		for (TActorIterator<ACharacter> ActorItr(World); ActorItr; ++ActorItr)
		{
			ACharacter* PlayerChar = *ActorItr;
			if (!PlayerChar)
				continue;

			// Log current state snapshot
			FVector CurrentLocation = PlayerChar->GetActorLocation();
			FRotator CurrentRotation = PlayerChar->GetActorRotation();
			FVector CurrentScale = PlayerChar->GetActorScale3D();

			UE_LOG(LogTemp, Display, TEXT("Test_PlayerCharacterStatePersistence: Location (%.1f, %.1f, %.1f)"),
				CurrentLocation.X, CurrentLocation.Y, CurrentLocation.Z);
			UE_LOG(LogTemp, Display, TEXT("Test_PlayerCharacterStatePersistence: Rotation (P=%.1f, Y=%.1f, R=%.1f)"),
				CurrentRotation.Pitch, CurrentRotation.Yaw, CurrentRotation.Roll);

			// Note: Full save/load test requires LoadGame/SaveGame cycle
			UE_LOG(LogTemp, Display, TEXT("Test_PlayerCharacterStatePersistence: State snapshot recorded"));
			UE_LOG(LogTemp, Display, TEXT("Test_PlayerCharacterStatePersistence: DEFERRED TO SAVE_SYSTEM_TEST"));

			return true;
		}

		UE_LOG(LogTemp, Warning, TEXT("Test_PlayerCharacterStatePersistence: No character found"));
		return true; // Non-fatal; not all worlds have player spawned
	}

