		UE_LOG(LogTemp, Display, TEXT("=== RESULTS: %d/5 criteria complete ==="), PassCount);
		UE_LOG(LogTemp, Display, TEXT("Note: Criteria 3, 4, 5 deferred to sleepwalker simulation (PIE + runtime measurement)"));

